        "name": "Part 7: Reading Comprehension",
        "passage": "Questions 19-23 refer to the following article.\nWhen developing a plan for a new business, the entrepreneur quite naturally wants to\neliminate all risk. While it is impossible to avoid some risk, the goal is to minimize it as much\nas possible. How can we do this? Thorough research and careful planning are the keys.\nThere are two parts to good research. First, you must demonstrate that there is a need for\nthe product or service you plan to offer. Are there enough people out there who would be\nwilling to pay for it? Second, you must look at your competition. What do you have to offer\nthat your competitors do not? Is your product or service of better quality in some way? Is it\ncheaper or more easily available? Is there a niche in the market that your competitors are\nnot addressing? If what you have to offer is identical to what your competitors are offering,\nyour business is not likely to be successful. These are some things to consider when\nevaluating how well you can measure up against the competition. Once you have evaluated\na need for your product or service and determined how yours will be different from your\ncompetitors', you are ready to begin the next part of your plan—financing.",
