        "passage": "Questions 19-23 refer to the following two e-mail messages.\nE-mail 1\nTo: Marjorie Morgan\nFrom: Bill Smithers\nSubject: Recruiting\nMarjorie,\nWe need to start looking at recruiting some\nnew staff members over the summer. Our\ncompany has gotten lots of new contracts\nrecently. We have abundant work and need\nto take on two or three new employees to\nhelp with it. We should advertise the\npositions as entry-level with room for\npromotion. We should choose the job\ncandidates carefully as I don't want to\nhave to end up firing anyone who turns out\nto be a bad match. I would like the new\nstaff members to start work by June 10.\nTherefore, we should ask interested\ncandidates to submit their applications\nbefore the end of April so that we can start\ninterviewing in early May. Please come up\nwith a recruiting plan and let me know.\nThanks.\nBill.\nE-mail 2\nTo: Bill Smithers\nFrom: Marjorie Morgan\nSubject: re: Recruiting\nAttachment: ad draft\nBill,\nHere is my plan for recruiting new staff\nmembers for this summer. I will place ads\nin our local newspapers, in two major\nnational papers, and on the major web\nsites by April 1. The deadline for\nsubmission of applications will be April 30.\nWe will start interviews on May 8. In the\nads I will carefully outline the\nqualifications we are looking for. I am\nattaching a draft of the ad. Please look it\nover and send me your comments. I want\nto make sure it contains all the details you\nwant.\nMarjorie",
