            "answer": "A",
            "explanation": "Câu cần một trạng từ để bổ nghĩa cho động từ \"performed\". \"Automatically\" có nghĩa là một cách tự động. Dịch nghĩa: Việc kiểm soát hàng tồn kho không thể được thực hiện một cách tự động, mà phải được thực hiện bằng cách đếm hàng hóa thực tế."
