        "passage": "Questions 19-23 refer to the following two e-mail messages.\nE-mail 1\nTo: Annabelle Pope\nFrom: Henry Rice\nSubject: Surgery\nHi Annabelle,\nI was wondering if you could help me\nout with something. My doctor has\nrecommended that I get knee\nreplacement surgery. I am trying to\nidentify the best hospital for this sort of\nprocedure. My doctor says she usually\nrecommends City Hospital, but I have\nheard that Upstate Hospital specializes\nin this kind of surgery. You had a similar\nprocedure last year, didn't you? I think\nyou broke your knee, or was it your\nelbow? Which hospital did you go to?\nWere you satisfied with the results of\nyour treatment, and were you well\ncared for by the staff? I would\nappreciate the benefit of your advice. I\nneed to make a decision soon since my\ndoctor thinks this should be done\nbefore another month goes by. Thanks.\nHenry\nE-mail 2\nTo: Henry Rice\nFrom: Annabelle Pope\nSubject: Re: Surgery\nHi Henry,\nI am sorry you need surgery, but I am sure you\nwill feel it is worth it. I had my procedure done\nat Upstate Hospital, and I would recommend\nthat place to anyone. The procedure I had was\nsimilar to yours, except it was my hip, not my\nknee. My surgeon was excellent, and I\nreceived good care from all the staff. The\nmission of the hospital is to provide the\nhighest level of care possible, and the entire\nstaff works hard to fulfill that mission. I was\noriginally told that I would need to be in the\nhospital for a week, but when it became clear\nthat I wouldn't be recovered enough by that\ntime, the doctor didn't hesitate to keep me\nthere for an extra three days. They wouldn't\npermit me to go home until they were sure I\nwas ready. I really think Upstate is the best\nhospital for your surgery. Let me know when it\nis scheduled, and I will visit you there.\nAnnabelle",
